import { useCallback, useMemo, useState } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import 'react-pdf/dist/esm/Page/AnnotationLayer.css';
import 'react-pdf/dist/esm/Page/TextLayer.css';

import { DocumentSigned } from 'components/icon/icons';
import { LoadingDots } from 'components/UI';

import {
  StyledDownloadButton,
  StyledHeader,
  StyledPageWrapper,
  StyledViewerContainer,
} from './PdfSlideViewer.styles';

pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.min.js`;

const PAGE_WIDTH = 1668;

const DownloadIcon = () => <DocumentSigned />;

export interface PdfSlideViewerProps {
  pdfUrl: string;
  onDownload?: () => void;
  dataTestId?: string;
}

export const PdfSlideViewer: React.FC<PdfSlideViewerProps> = ({
  pdfUrl,
  onDownload,
  dataTestId = 'pdf-slide-viewer',
}) => {
  const [numPages, setNumPages] = useState<number>(0);

  const onDocumentLoadSuccess = useCallback(
    ({ numPages: total }: { numPages: number }) => {
      setNumPages(total);
    },
    [],
  );

  const handleDownload = useCallback(() => {
    if (onDownload) {
      onDownload();
      return;
    }

    const link = document.createElement('a');
    link.href = pdfUrl;
    link.download = 'document.pdf';
    document.body.appendChild(link);
    link.click();
    link.remove();
  }, [onDownload, pdfUrl]);

  const pageNumbers = useMemo(
    () => Array.from({ length: numPages }, (_, i) => i + 1),
    [numPages],
  );

  return (
    <StyledViewerContainer data-testid={dataTestId}>
      <StyledHeader>
        <StyledDownloadButton
          data-testid={`${dataTestId}-download`}
          variant="primary"
          size="medium"
          onClick={handleDownload}
          icon={DownloadIcon}
          trailing
        >
          Download PDF
        </StyledDownloadButton>
      </StyledHeader>

      <Document
        file={pdfUrl}
        onLoadSuccess={onDocumentLoadSuccess}
        loading={<LoadingDots />}
        error={<span>Failed to load PDF.</span>}
      >
        {pageNumbers.map((pageNumber) => (
          <StyledPageWrapper
            key={pageNumber}
            data-testid={`${dataTestId}-page-${pageNumber}`}
          >
            <Page
              pageNumber={pageNumber}
              renderTextLayer
              renderAnnotationLayer
              width={PAGE_WIDTH}
            />
          </StyledPageWrapper>
        ))}
      </Document>
    </StyledViewerContainer>
  );
};
